document.addEventListener('keydown',async e=>{if(!['Enter',' '].includes(e.key)||e.target.closest('button,input,select'))return;const card=e.target.closest('[data-open-person],[data-open-film],[data-open-tv]');if(!card)return;e.preventDefault();try{await openCard(card)}catch(err){error=err.message;render()}});
function mainNavFocus(){document.querySelector('#mainNav button.active')?.focus()}
function applyTheme(){document.documentElement.style.setProperty('--accent',state.preferences?.accent||'#3bdd0e')}
async function restoreSavedView(){try{if(seriesId){await loadSeries(seriesId)}else if(film){const id=film;const m=await request('/api/movie/'+id);filmCache.set(id,m);if(film===id)render()}else if(selected){const id=selected;const p=state.following[id]||knownPeople.get(id)||{id,name:'Filmographie',role:'actor'};currentPerson=p;await loadPerson(p);await loadPersonSeries(id)}else if(tab==='now-playing')await loadNowPlaying();else if(tab==='series')await loadSeriesHome()}catch(e){error=e.message;render()}}
onAuthStateChanged(auth,u=>{authReady=!u;user=u;menuOpen=false;mobileNavOpen=false;unsub?.();unsub=null;state={following:{},statuses:{},dismissed:{},seenAt:{},preferences:{accent:'#3bdd0e'}};applyTheme();people.clear();knownPeople.clear();filmCache.clear();seriesCache.clear();seriesSeasonCache.clear();personSeriesCache.clear();restoredView=false;if(u){unsub=onSnapshot(doc(db,'users',u.uid,'data','movieQuest'),snap=>{if(snap.exists())state={following:{},statuses:{},dismissed:{},seenAt:{},series:{},preferences:{accent:'#3bdd0e'},...snap.data()};applyTheme();authReady=true;if(!restoredView){restoredView=true;restoreSavedView()}if(tab==='explore'&&!selected&&!film&&!seriesId&&!document.body.classList.contains('app-booting')){for(const id of Object.keys(state.following))updateFollowControls(id);document.querySelectorAll('[data-follow]').forEach(b=>updateFollowControls(b.dataset.follow))}else if(selected&&!document.body.classList.contains('app-booting')){updateFollowControls(selected)}else render();loadFollowing()},e=>{error=e.message;authReady=true;render()})}if(!u){render()}},e=>{error='Impossible de vérifier la session Google : '+e.message;user=null;authReady=true;render()});